const mondayBoardVisible=false; // Temporary panel visibility; integration configuration is preserved.
let C,session,taskCatalog=null,records=[],members=[],audit=[],view=['training','results'].includes(location.hash.slice(1))?(location.hash.slice(1)==='training'?'panel':'results'):(location.hash.slice(1)||'panel'),tab='today',area='all',date='',search='',service='hair',queueTab='now',busy=false,syncError=false,lastSync='',refreshInFlight=0;const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label={unconfirmed:"Presença a confirmar",done:'Concluída',pending:'Pendente',partial:'Parcial',blocked:'Bloqueada',na:'Não se aplica',open:'Aberta',progress:'Em andamento',resolved:'Resolvida',contacted:'Contato feito',scheduled:'Agendada',completed:'Concluída',dismissed:'Encerrada',daily:'Diária',weekly:'Semanal',monthly:'Mensal',three:'3× na semana',demand:'Sob demanda',review:'Revisar regra',present:'Presente',absent:'Ausente',occupied:'Ocupada'};
const dayNames=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];const management=()=>['admin','manager'].includes(session?.role);const byKind=kind=>records.filter(r=>r.kind===kind);const record=id=>records.find(r=>r.id===id);const titleDate=d=>new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});const fmtDate=d=>d?d.slice(0,10).split('-').reverse().join('/'):'Sem prazo';const pill=(s,text)=>`<span class="pill ${['done','resolved','completed','present','scheduled'].includes(s)?'green':['blocked','absent'].includes(s)?'red':['partial','pending','occupied','progress'].includes(s)?'gold':''}">${e(text||label[s]||s)}</span>`;
const btn=(action,text,id='',cls='')=>{if(session?.temporaryReadOnly&&['run','trigger','routine','inventory','stock','entry','activation','new-activation-kind','client','member','staff-schedule','stock-policy','stock-coverage-policy','stock-catalog-activate','queue-add','queue-status','queue-depart','queue-pass','queue-attend','queue-schedule','appointment-confirm','appointment-no-show','queue-unschedule','avec-upload'].includes(action))return '';if((['routine','inventory','stock-policy','stock-coverage-policy','stock-catalog-activate','staff-schedule'].includes(action)&&!management())||(action==='member'&&session?.role!=='admin')||(action==='client'&&!id&&!management())||(['run','trigger'].includes(action)&&!canKind(session?.role,'run')))return '';return `<button type="button" class="btn ${cls}" data-action="${e(action)}" data-id="${e(id)}">${text}</button>`};
const field=(name,title,value='',type='text',required=false,extra='')=>`<label><span class="field-label">${e(title)}</span><input class="field" name="${e(name)}" type="${e(type)}" value="${e(value)}" ${required?'required':''} ${extra}></label>`;
const textarea=(name,title,value='')=>`<label><span class="field-label">${e(title)}</span><textarea class="field" name="${e(name)}" maxlength="4000">${e(value)}</textarea></label>`;
const select=(name,title,options,value='')=>`<label><span class="field-label">${e(title)}</span><select name="${e(name)}" class="field">${options.map(([v,l])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(l)}</option>`).join('')}</select></label>`;
const empty=t=>`<div class="empty">${e(t)}</div>`;
const summary=(title,sub,action='')=>`<div class="head"><div>${title?`<h1>${title}</h1>`:''}${sub?`<p class="sub">${sub}</p>`:''}</div><div class="actions">${action}</div></div>`;
async function request(path,body){if(session?.temporaryReadOnly&&body)throw Error('Este link permite somente consultar o painel.');const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('Não foi possível ler a resposta do servidor.')}if(!response.ok)throw Object.assign(Error(data.error||'Não foi possível concluir.'),{status:response.status});return data}
function toast(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.className=error?'error':'';t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',5500)}
async function refresh(renderNow=true){refreshInFlight++;try{await openTemporaryView();const data=await request('/api/bootstrap');if(session&&(session.id!==data.user.id||session.role!==data.user.role||assistantIdentity!==data.assistantIdentity))resetPanelAssistant();assistantIdentity=data.assistantIdentity||'';session=data.user;if(area!=='all'&&!canArea(session.role,area))area=Object.keys(areas).find(id=>canArea(session.role,id))||'all';records=data.records;members=data.members;taskCatalog=Array.isArray(data.tasks)?data.tasks:null;if(!date)date=data.today;await refreshFeatures();if(view==='clients')await refreshSubmittedProfiles();if(mondayBoardVisible&&['panel','commercial'].includes(view)&&!assistantState.board&&!assistantState.boardError&&!assistantState.boardBusy&&!session.temporaryReadOnly)refreshPanelBoard(false);lastSync=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});const recoveredConnection=syncError;syncError=false;if(renderNow&&!dialog.open&&!document.querySelector('input:focus,textarea:focus,select:focus')){const signature=JSON.stringify({submittedProfiles,profileError,records,members,taskCatalog,presence:presenceState.shifts,events:presenceState.events,avecSummary,stockState,resultState,importState});if(recoveredConnection||refresh.signature!==signature){refresh.signature=signature;render()}}}catch(err){if([401,403].includes(err.status))clearPrivateSession();syncError=true;if(!session){app.innerHTML=`<div class="loading"><div class="wordmark">E.Lab Hub<span>BOUTIQUE</span></div><p>${e(err.message)}</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Entrar com ChatGPT</a>${btn('retry','Tentar novamente')}</div>`}else if(renderNow&&!dialog.open&&!document.querySelector('input:focus,textarea:focus,select:focus'))render();throw err}finally{refreshInFlight--}}
function scopedRecords(kind){return byKind(kind).filter(r=>canArea(session.role,recordArea(r,tasks()))&&(area==='all'||recordArea(r,tasks())===area))}
function tasks(){const map=new Map((taskCatalog||C.tasks).map(t=>[t.id,t]));byKind('routine').forEach(r=>map.set(r.id,{...r.data,id:r.id}));return [...map.values()]}
function instances(day=date,all=false){return tasks().filter(t=>(all||due(t,day))&&(area==='all'||t.area===area)&&canArea(session.role,t.area)).flatMap(t=>Array.from({length:t.schedule==='three'?3:1},(_,i)=>{const key=instanceKey(t,day,i+1),r=record('run/'+key);return {task:t,id:'run/'+key,run:r,slot:i+1,date:day,status:r?.data.status||'pending'}}))}
function runRow(item){const {task,run,status}=item;const canRun=canKind(session.role,'run')&&!session.temporaryReadOnly;if(['hr','adm'].includes(session?.role))return '<div class="row"><div class="row-body"><div class="row-title">'+e(task.title)+'</div><p>'+e(areas[task.area])+' · '+e(task.when)+'</p></div>'+pill(status)+'</div>';return `<div class="row">${canRun?`<button class="check ${status==='done'?'done':''}" data-action="run" data-id="${e(item.id)}" data-date="${e(item.date)}" aria-label="Registrar ${e(task.title)}">${status==='done'?'✓':status==='blocked'?'!':''}</button>`:''}<div class="row-body"><div class="row-title">${e(task.title)}${task.schedule==='three'?` · ${item.slot}ª ocorrência`:''}</div><p>${e(areas[task.area])} · ${e(task.when)}${run?.data.responsible?' · '+e(run.data.responsible):''}</p>${run?.data.note?`<p>${e(run.data.note)}</p>`:''}</div>${pill(status)}${btn('run','Registrar',item.id,'small')}</div>`}
function entryRow(r){return `<div class="row"><span class="badge-icon">${r.data.type==='unmet'?'↗':'!'}</span><div class="row-body"><div class="row-title">${e(r.data.title)}</div><p>${e(r.data.responsible||'Sem responsável')} · ${fmtDate(r.data.due)}${r.data.client?' · '+e(r.data.client):''}</p></div>${pill(r.data.status)}${btn('entry','Abrir',r.id,'small')}</div>`}
const retiredActivationLabels={pos_google:'Pós-atendimento — Avaliação Google',corte_masc:'Corte Masculino',podologia:'Podologia',massagem:'Massagem'};
function activationLabel(id){return C.ATIVACOES.find(a=>a.id===id)?.nome||retiredActivationLabels[id]||id}
function activationEvolution(r){const events=byKind('activation_event').filter(v=>v.data.activationId===r.id).sort((a,b)=>a.data.at.localeCompare(b.data.at));return events.length?`<details data-detail-key="activation-history:${e(r.id)}"><summary>Evolução · ${events.length} registros</summary>${events.map(v=>`<p class="help">${e(safeTime(v.data.at))} · ${e(label[v.data.toStatus]||v.data.toStatus)} · ${e(v.data.responsible||v.data.actor)}${v.data.note?' · '+e(v.data.note):''}</p>`).join('')}</details>`:''}
function activationRow(r){return `<div class="row"><span class="badge-icon">↗</span><div class="row-body"><div class="row-title">${e(r.data.client)}</div><p>${e(activationLabel(r.data.kind))} · ${fmtDate(r.data.due)}</p><p>${e(r.data.responsible||'Sem responsável')}${r.data.stage?' · '+e(r.data.stage):''}</p></div>${pill(r.data.status)}${btn('activation','Acompanhar',r.id,'small')}</div>${activationEvolution(r)}`}
function filters(){return `<div class="filters"><input class="field" type="date" id="dateFilter" value="${e(date)}" aria-label="Data da operação"><select class="field" id="areaFilter" aria-label="Filtrar setor"><option value="all" ${area==='all'?'selected':''}>Todos</option>${Object.entries(areas).filter(([id])=>canArea(session.role,id)).map(([id,l])=>`<option value="${id}" ${area===id?'selected':''}>${l}</option>`).join('')}</select>${btn('today','Voltar para hoje','','small')}</div>`}
function dailyActivations(){const dow=new Date(date+'T12:00:00Z').getUTCDay();const due=C.ATIVACOES.filter(a=>/di[áa]ri[oa]/i.test(a.freq)||(/semanal/i.test(a.freq)&&a.dow?.includes(dow)));return due.map(a=>`<div class="row"><div class="row-body"><strong>${e(a.nome)}</strong></div>${btn('new-activation-kind','Trabalhar',a.id,'small')}</div>`).join('')||empty('Sem ativações previstas.')}
function ownerOverview() {
 const from=date.slice(0,7)+'-01';
 const report=performanceReport(resultState.services.filter(r=>isOperationalName(r.data.normalized.professional)),from,date);
 return `<section class="card"><div class="card-head"><h2>Indicadores do salão · ${date.slice(5,7)}/${date.slice(0,4)}</h2><div class="actions">${btn('navigate','Resultados','results')}${btn('navigate','Estoque','inventory')}</div></div>${performanceCards(report)}</section><div class="divider"></div>${teamAvailability()}`;
}
function routineProgress(done,total){
 const pct=total?Math.round(done/total*100):0;
 return `<section class="card day-progress routine-progress"><div class="ring" style="--pct:${pct}" role="img" aria-label="${pct}% das rotinas aplicáveis concluídas"><div><strong>${pct}%</strong><small>Concluídas</small></div></div><div><h2>Progresso das rotinas</h2><p>${done} de ${total} rotinas aplicáveis</p><p class="help">${e(areas[area]||'Todos os setores')} · ${fmtDate(date)}</p></div></section>`;
}
let assistantIdentity='';
let integrationState=null;
async function loadIntegrationStatus(){const rev=assistantEpoch,id=session?.id,scope=assistantIdentity,current=()=>rev===assistantEpoch&&id===session?.id&&scope===assistantIdentity;try{const result=await request('/api/integration-status');if(current())integrationState=result}catch(err){if(current())integrationState={error:err.message}}if(current())render()}
let assistantState={draft:'',history:[],busy:false,board:null,boardBusy:false,boardError:'',boardStatus:'open',boardOwner:''},assistantEpoch=0;
function resetPanelAssistant(){integrationState=null;assistantEpoch++;procedureEpoch++;procedureAnswer=null;procedureDraft='';procedureBusy=false;assistantState={draft:'',history:[],busy:false,board:null,boardBusy:false,boardError:'',boardStatus:'open',boardOwner:''}}
function assistantSections(){
 if(!session||session.temporaryReadOnly||(!management()&&!['hr','adm'].includes(session.role)&&!roleArea(session.role)))return '';
 const state=assistantState,answer=state.history.at(-1)?.answer;
 const messages=state.history.map(({query,answer:r})=>`<article class="assistant-turn"><p class="assistant-question">${e(query)}</p><div class="assistant-reply"><span class="label">${e(({web:'Orientação externa · não é um POP',drive:'Base interna · Drive',internal:'Catálogo interno',saved:'Rotina registrada','monday-saved':'Monday atualizado'})[r.kind]||'Assistente E.Lab')}</span><p class="assistant-message">${e(r.message)}</p>${r.options?.length?`<ul>${r.options.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:''}${r.matches?.map(x=>`<div class="assistant-source"><strong>${e(x.title)}</strong><ol>${x.steps.map(step=>`<li>${e(step)}</li>`).join('')}</ol></div>`).join('')||''}${r.sources?.length?`<ul class="assistant-sources">${r.sources.map(x=>`<li>${x.url?`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.title)}</a>`:e(x.title)}</li>`).join('')}</ul>`:''}</div></article>`).join('');
 const assist=`<section class="card panel-assistant"><h2>Assistente E.Lab</h2><p class="help">Dúvidas e rotina do seu setor.</p><div class="assistant-thread" role="log" aria-live="polite">${messages}</div><form id="panelAssistantForm"><label><span class="field-label">Mensagem</span><textarea id="panelAssistantInput" class="field" name="message" rows="2" maxlength="1500" required placeholder="Ex.: Como faço o fechamento de caixa?">${e(state.draft)}</textarea></label><div class="actions"><button class="btn primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Consultando…':'Enviar'}</button>${answer?.offerWeb&&!state.busy?btn('panel-web','Buscar na internet'):''}${answer?.kind==='monday-confirm'&&!state.busy?btn('panel-monday-confirm','Confirmar no Monday',answer.itemId):''}</div></form></section>`;
 const board=state.board;
 const selectOptions=[['open','Em aberto'],['all','Todos'],['A fazer','A fazer'],['Em andamento','Em andamento'],['Aguardando','Aguardando'],['Concluído','Concluído'],['Cancelado','Cancelado']];
 const owners=[...new Set((board?.items||[]).flatMap(x=>x.owner.split(',').map(v=>v.trim()).filter(Boolean)))].sort();
 const rows=(board?.items||[]).filter(x=>(state.boardStatus==='all'||(state.boardStatus==='open'?!['Concluído','Cancelado'].includes(x.status):x.status===state.boardStatus))&&(!state.boardOwner||x.owner.split(',').map(v=>v.trim()).includes(state.boardOwner))).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));
 const block=`<section class="card panel-assistant"><div class="card-head"><h2>Quadro E.Lab</h2></div>${state.boardError?`<p class="notice error" role="alert">${e(state.boardError)}</p>`:''}${board?.connected?`<div class="assistant-filters"><label><span class="field-label">Status</span><select class="field" id="panelBoardStatus">${selectOptions.map(([key,title])=>`<option value="${e(key)}" ${key===state.boardStatus?'selected':''}>${e(title)}</option>`).join('')}</select></label><label><span class="field-label">Responsável</span><select class="field" id="panelBoardOwner"><option value="">Todos</option>${owners.map(x=>`<option value="${e(x)}" ${x===state.boardOwner?'selected':''}>${e(x)}</option>`).join('')}</select></label></div><div class="table-wrap monday-board-table"><table class="audit-table"><thead><tr><th>Item</th><th>Responsável</th><th>Data limite</th><th>Status</th><th>Prioridade</th></tr></thead><tbody>${rows.map((x,i)=>`${x.groupTitle&&(!i||rows[i-1].groupTitle!==x.groupTitle)?`<tr class="monday-group"><th colspan="5">${e(x.groupTitle)}</th></tr>`:''}<tr><th scope="row">${e(x.title)}</th><td>${e(x.owner||'—')}</td><td>${e(x.due?fmtDate(x.due):'—')}</td><td>${pill(x.status==='Concluído'?'done':'pending',x.status||'Sem status')}</td><td>${e(x.priority||'—')}</td></tr>`).join('')||'<tr><td colspan="5">Não há itens neste filtro.</td></tr>'}</tbody></table></div>${board.more?`<p class="help">Mostrando os primeiros 500 registros.</p>`:''}`:board?'<p class="help">Conexão com o quadro indisponível.</p>':''}<div class="actions">${state.boardBusy?'<span role="status">Consultando o quadro…</span>':btn('panel-board-refresh',board?.connected?'Atualizar quadro':'Carregar quadro do Monday')}</div></section>`;
 return `<div class="grid equal panel-assistant-grid ${mondayBoardVisible?'':'assistant-only'}">${assist}${mondayBoardVisible?block:''}</div>`;
}
async function refreshPanelBoard(renderNow=true){
 const s=assistantState,rev=assistantEpoch;
 if(!mondayBoardVisible||s.boardBusy||!session||session.temporaryReadOnly)return;
 s.boardBusy=true;s.boardError='';if(renderNow)render();
 try{s.board=await request('/api/panel-monday')}catch(err){s.boardError=err.message}
 finally{if(rev===assistantEpoch){s.boardBusy=false;if(renderNow||!document.querySelector('#panelAssistantInput:focus'))render()}}
}
async function sendPanelChat(mode='message',itemId=''){
 const s=assistantState,rev=assistantEpoch;
 if(s.busy||!session||session.temporaryReadOnly)return;
 const last=s.history.at(-1);
 const query=mode==='web'?last?.query:mode==='monday'?last?.query:document.querySelector('#panelAssistantInput')?.value.trim();
 if(!query)return;
 s.busy=true;if(mode==='message')s.draft=query;render();
 let answer;
 try{
  answer=mode==='monday'?await request('/api/panel-monday',{action:'confirm-complete',itemId}):await request('/api/panel-assistant',{message:query,area,web:mode==='web'});
  if(rev!==assistantEpoch)return;
  if(answer.record){records=[answer.record,...records.filter(r=>r.id!==answer.record.id)];await refresh(false).catch(()=>{})}
  if(answer.kind==='monday-saved'||answer.kind==='monday-already')await refreshPanelBoard();
  if(rev!==assistantEpoch)return;
  if(mode==='message')s.draft='';
 }catch(err){answer={kind:'error',message:err.message}}
 finally{
  if(rev===assistantEpoch){
   s.busy=false;s.history=[...s.history,{query:mode==='web'?'Buscar orientação externa':mode==='monday'?'Confirmar conclusão no Monday':query,answer}].slice(-8);
   render();
  }
 }
}

function routineEmptyState(){const configured=tasks().some(t=>canArea(session.role,t.area)&&(area==='all'||t.area===area));return configured?empty('Nenhuma rotina prevista nesta data.'):`<div class="empty">Nenhuma rotina configurada para este setor.${management()?btn('routine','Configurar rotina','','small'):''}</div>`}
function operationsPanel() {
 const list=instances(),applicable=list.filter(x=>x.status!=='na'),done=applicable.filter(x=>x.status==='done').length;
 const entries=scopedRecords('entry').filter(r=>r.data.status!=='resolved');
 const reception=canKind(session.role,'activation');
 const activations=reception?scopedRecords('activation').filter(r=>!['completed','dismissed'].includes(r.data.status)):[];
 const next=activations.filter(r=>r.data.due&&r.data.due<=date);
 const blocked=list.filter(x=>['blocked','partial'].includes(x.status));
 const attention=blocked.length+entries.filter(r=>r.data.due&&r.data.due<date).length;
 const blocks=[['Acompanhar',activations.length,'ativações em andamento'],['Próximos passos',next.length,'ações com prazo até hoje'],['Pendências',applicable.length-done,'rotinas a concluir'],['Precisa de atenção',attention,'bloqueios ou registros vencidos']];
 return filters()+`<div class="panel-overview">`+routineProgress(done,applicable.length)+
  `<div class="card mini-stats">${blocks.map(([title,count,label])=>`<div class="mini-stat"><h2>${title}</h2><strong>${count}</strong><p>${label}</p></div>`).join('')}</div></div>`+assistantSections()+
  (canKind(session.role,'entry')?`<div class="actions" style="margin-top:16px">${btn('entry','＋ Novo registro')}</div>`:'')+
  tabs([['today','Hoje'],['week','Semana'],['catalog','Cronograma'],...(reception?[['matrix','Ativações'],['relationships','Relacionamento']]:[])])+
  (tab==='catalog'?routinePage():tab==='week'?weekView():reception&&tab==='matrix'?matrixView():reception&&tab==='relationships'?
    `<section class="card"><h2>Relacionamento</h2>${activations.map(activationRow).join('')||empty('Sem acompanhamentos abertos.')}</section>`:
    `<div class="grid"><section class="card"><div class="card-head"><h2>Rotina do dia</h2><span class="pill">${done}/${applicable.length} concluídas</span></div><div class="scroll-area">${list.map(runRow).join('')||routineEmptyState()}</div></section>
    <div class="stack"><section class="card"><h2>Precisa de atenção</h2>${blocked.slice(0,3).map(runRow).join('')}${entries.slice(0,4).map(entryRow).join('')}${blocked.length||entries.length?'':empty('Sem pendências.')}${entries.length>4?btn('go-entries',`Ver todas (${entries.length})`):''}</section>
    ${(area==='commercial'||area==='all'&&canArea(session.role,'commercial'))?`<section class="card"><h2>Conversas que continuam</h2>${dailyActivations()}${next.slice(0,4).map(activationRow).join('')}</section>`:''}</div></div>`)+
  `<div class="divider"></div>${teamAvailability()}`+(management()&&!session.temporaryReadOnly?managementSettings():'');
}
function tabs(options,active=tab){return `<div class="tabs">${options.map(([id,l])=>`<button class="tab ${active===id?'active':''}" data-action="tab" data-id="${id}">${e(l)}</button>`).join('')}</div>`}
function weekView(){const start=weekStart(date);return `<section class="card"><div class="card-head"><div><h2>Rotina da semana</h2></div></div><div class="week">${Array.from({length:7},(_,i)=>addDays(start,i)).map(d=>{const rows=instances(d),n=rows.filter(x=>x.status==='done').length;return `<div class="day ${d===businessDate()?'today':''}"><div class="label">${dayNames[new Date(d+'T12:00:00Z').getUTCDay()]} · ${d.slice(8)}</div><p>${n}/${rows.length} execuções</p>${[...new Set(rows.map(x=>x.task.title))].slice(0,5).map(t=>`<p>· ${e(t)}</p>`).join('')}${rows.length>5?'<p>Mais tarefas no dia</p>':''}${btn('open-day','Abrir dia',d,'small')}</div>`}).join('')}</div></section>`}
function matrixView(){return `<div class="grid equal">${C.ATIVACOES.map(a=>`<section class="card"><div class="card-head"><h3>${e(a.nome)}</h3>${pill('gold',a.freq)}</div><p class="meta"><strong>Público:</strong> ${e(a.publico)}</p><p class="meta"><strong>Quando:</strong> ${e(a.dia)}</p><p style="margin:14px 0;font-size:13px">${e(a.criterio)}</p>${canKind(session.role,'activation')?btn('new-activation-kind','Executar ativação',a.id,'small'):''}</section>`).join('')}</div>`}
function recordsView(){const rows=scopedRecords('run');return `<section class="card"><div class="card-head"><div><h2>Histórico de execução</h2><p>Registros persistentes, com autoria e evidência.</p></div>${btn('history-export','Baixar histórico','routines')}</div>${rows.map(r=>`<div class="row"><div class="row-body"><div class="row-title">${e(r.data.title)}</div><p>${fmtDate(r.data.date)} · ${e(r.updatedBy)} · ${e(r.data.responsible)}</p><p>${e(r.data.note)}</p>${r.data.evidence?`<p>Evidência: ${e(r.data.evidence)}</p>`:''}</div>${pill(r.data.status)}${btn('run','Abrir',r.id,'small')}</div>`).join('')||empty('Os registros aparecem aqui após a primeira execução.')}</section>`}
