function safeTime(at){if(!at)return 'Sem data na origem';if(/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d)?$/.test(at))return fmtDate(at)+' '+at.slice(11,16)+' (horário informado)';const n=Date.parse(at);return Number.isFinite(n)?new Date(n).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):String(at)}
