let procedureSector = '';
const normalizeProcedure = value => value.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().trim();

function procedureFavorites() {
  try {
    const saved = JSON.parse(localStorage.getItem('elab-procedure-favorites:' + (assistantIdentity||session.id)) || '[]');
    return new Set(Array.isArray(saved) ? saved : []);
  } catch {
    return new Set();
  }
}

function toggleProcedureFavorite(id) {
  const favorites = procedureFavorites();
  if (favorites.has(id)) favorites.delete(id);
  else favorites.add(id);
  localStorage.setItem('elab-procedure-favorites:' + (assistantIdentity||session.id), JSON.stringify([...favorites]));
  render();
}

// Match situations with a procedure only when the query includes the defining facts.
function procedureSituation(value) {
  const query = normalizeProcedure(value);
  if (!value.includes('?') && query.split(/\s+/).length < 6) return null;
  const scenarios = [
    ['espera', /client/, /atras|espera|demor/],
    ['agendamento', /agend|remarc|encaix/, /horario|prefer|client|agenda/],
    ['listadavez', /vez|fila/, /ausent|faltou|presen|ocupad|encaix/],
    ['caixa', /caixa|comprovante/, /fech|diverg|confer/],
    ['cadastro', /cadastr/, /client|telefone|dados/],
    ['revenda', /revend|produto/, /indic|recomend/],
  ];
  const matches = scenarios.filter(([, subject, condition]) => subject.test(query) && condition.test(query));
  return {id: matches.length === 1 ? matches[0][0] : undefined};
}

let procedureEpoch=0,procedureAnswer=null,procedureBusy=false,procedureDraft="";
async function askProcedure(){
 if(procedureBusy)return;const rev=procedureEpoch,question=document.querySelector('#procedureQuestion')?.value||'';procedureBusy=true;
 const button=document.querySelector('[data-action=procedure-ask]');if(button){button.disabled=true;button.textContent='Consultando…'}
 try{const answer=await request('/api/procedure-consult',{question});if(rev===procedureEpoch)procedureAnswer={question,...answer}}
 catch(err){if(rev===procedureEpoch)procedureAnswer={question,error:err.message}}
 finally{if(rev===procedureEpoch){procedureBusy=false;render()}}
}
