function legacyImportModal(){modal('Importar registros de outro aparelho',`<div class="notice">Use o JSON da Lista da Vez original, do painel integrado ou o pacote exportado do navegador antigo. A importação acrescenta histórico e preserva o cadastro atual da fila.</div>${field('source','Nome da origem / aparelho','Navegador da recepção','text',true)}<label><span class="field-label">Arquivo de histórico</span><input class="field" name="file" type="file" accept="application/json" required></label><p class="help">Somente arquivos de histórico são aceitos aqui. Relatórios Avec terão mapeamento próprio, após conferência das colunas.</p>`,'Conferir e importar',async(f,form)=>{const file=form.elements.file.files[0];if(file.size>1500000)throw Error('Divida o arquivo: limite de 1,5 MB por importação.');const payload=JSON.parse(await file.text()),preview=legacyCandidates(payload);if(!preview.length)throw Error('Nenhum histórico compatível encontrado.');if(!confirm(`Foram encontrados ${preview.length} registros ou snapshots. Importar sem sobrescrever a fila atual?`))throw Error('Importação cancelada.');const r=await request('/api/legacy-import',{payload,source:f.source});toast(`${r.inserted} incorporados; ${r.skipped} já existentes.`)})}
