function commitView(html){
 const oldShell=app.querySelector('.shell');
 if(!oldShell||!document.createElement){app.innerHTML=html;return}
 const template=document.createElement('template');template.innerHTML=html;
 const next=template.content;
 for(const selector of ['main','.topbar']){const old=app.querySelector(selector),fresh=next.querySelector(selector);if(old&&fresh&&old.innerHTML!==fresh.innerHTML)old.replaceWith(fresh)}
 const oldNav=app.querySelector('nav'),nextNav=next.querySelector('nav');
 if(oldNav&&nextNav){const oldButtons=[...oldNav.querySelectorAll('button')],newButtons=[...nextNav.querySelectorAll('button')];if(oldButtons.map(x=>x.dataset.id).join()!==newButtons.map(x=>x.dataset.id).join()){oldNav.innerHTML=nextNav.innerHTML}else oldButtons.forEach((b,i)=>{b.className=newButtons[i].className;b.disabled=newButtons[i].disabled;b.title=newButtons[i].title;b.setAttribute('aria-current',newButtons[i].getAttribute('aria-current'))})}
}
function render(){if(!C||!session)return;if(view==='results'&&!canViewIndicators(session))view='panel';if(view==='commercial')area='commercial';const openDetails=new Set(Array.from(app.querySelectorAll?.('details[data-detail-key][open]')||[],item=>item.dataset.detailKey));const managementOpen=app.querySelector('[data-management-settings]')?.open;const openProcedures=new Set(Array.from(app.querySelectorAll?.('details[data-procedure][open]')||[], item=>item.dataset.procedure));const nav=[['panel','◷','Painel'],['commercial','↗','Comercial'],['presence','✓','Presença'],['queue','⇄','Lista da Vez'],['routines','☷','Rotinas'],['relations','↗','Relacionamento'],['inventory','□','Estoque'],['replenishment','↻','Estoque'],['results','▥','Indicadores'],['clients','♡','Meu Perfil'],['procedures','⌕','Procedimentos'],['training','◇','Classes'],['imports','⇧','Central AVEC'],['history','◴','Histórico']].filter(([id])=>id!=='training'&&!(session.role==='commercial'&&id==='presence')&&!(id==='commercial'&&!canArea(session.role,'commercial'))&&!(id==='imports'&&!canImport())&&!(id==='replenishment'&&!canStock())&&!(id==='results'&&!management()&&!['reception','commercial'].includes(session.role))&&!(['relations'].includes(id)&&!canKind(session.role,'entry'))&&!(['queue','clients','inventory'].includes(id)&&!canKind(session.role,({queue:'queue',clients:'client',inventory:'inventory'})[id]))&&!(id==='manage'&&!management()));if(!nav.some(n=>n[0]===view))view='panel';const titles=Object.fromEntries(nav.map(x=>[x[0],x[2]]));const body=({presence:presencePage,imports:importsPage,results:resultsPage,replenishment:replenishmentPage,panel,commercial:commercialPage,routines:routinePage,relations,queue:queuePage,clients:clientPage,inventory:inventoryPage,procedures:proceduresPage,training:trainingPage,history:historyPage})[view];commitView(`<div class="shell"><aside class="sidebar"><div class="mobile-header"><div class="wordmark">E.Lab Hub<span>BOUTIQUE</span></div><button type="button" class="btn menu-toggle" aria-controls="main-nav" aria-expanded="false" data-action="toggle-menu">Menu</button></div><nav id="main-nav" aria-label="Navegação principal">${nav.filter(([id])=>!['history','replenishment','routines','relations','training'].includes(id)).map(([id,icon,t])=>`<button ${id==='results'&&!canViewIndicators(session)?'disabled title="Entre com uma conta autorizada para acessar os Indicadores"':''} class="${id==='results'&&!canViewIndicators(session)?'nav-locked ':''}${(view===id||(id==='inventory'&&view==='replenishment'))?'active':''}" aria-current="${view===id||(id==='inventory'&&view==='replenishment')?'page':'false'}" data-action="navigate" data-id="${id}"><span class="navicon" aria-hidden="true">${icon}</span>${t}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="label" style="margin:0 0 8px">E.Lab Hub · 2.4</div></div></aside><div class="page-content"><header class="topbar"><div class="breadcrumb">E.Lab Hub <span style="padding:0 12px;color:#a67c3d">/</span><strong>${e(titles[view])}</strong></div><div class="user"><span class="sync"><i class="dot" style="${syncError?'background:#b57152':''}"></i>${syncError?'Conexão interrompida':`Atualizado às ${lastSync}`}</span><span class="avatar">${e(session.name[0]?.toUpperCase())}</span><div>${e(roles[session.role])}</div></div></header><main>${session.testAccess?'<div class="notice">Acesso de teste · Hub liberado sem login</div>':''}${session.temporaryReadOnly?'<div class="notice">Acesso temporário · Somente para consulta</div>':''}${syncError?'<div class="notice error">Sem conexão para atualizar o painel.</div>':''}${body()}<footer class="footer"><span>E.Lab Boutique</span></footer></main></div></div>`);for(const item of app.querySelectorAll?.('details[data-detail-key]')||[])if(openDetails.has(item.dataset.detailKey))item.open=true;const settings=app.querySelector('[data-management-settings]');if(settings&&managementOpen)settings.open=true;for(const item of app.querySelectorAll?.('details[data-procedure]')||[])if(openProcedures.has(item.dataset.procedure))item.open=true}
