function modal(title,content,submit,onSubmit){dialog.innerHTML=`<div class="card-head"><h2>${e(title)}</h2><button class="close" data-action="close" aria-label="Fechar">×</button></div><form class="form" id="modalForm">${content}<div id="formError" class="notice error" hidden></div><div class="form-footer">${btn('close','Cancelar')}<button type="submit" class="btn primary">${e(submit)}</button></div></form>`;if(!dialog.open)dialog.showModal();dialog.querySelector('form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const b=dialog.querySelector('[type=submit]');b.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(ev.target)),ev.target);dialog.close();await refresh();toast('Registro salvo.')}catch(err){const box=dialog.querySelector('#formError');box.hidden=false;box.textContent=err.message;if(/alter|atualiz/.test(err.message))await refresh(false)}finally{busy=false;b.disabled=false}}}
async function saveRecord(kind,data,r,id){const result=await request('/api/save',{kind,data,id:r?.id||id,revision:r?.revision||0});return result}
function runModal(id,day=date,trigger=false){let r=record(id),t=tasks().find(t=>t.id===(r?.data.taskId||id.replace(/^run\//,'').split('/')[0]));if(!t)return toast('Rotina não encontrada.',true);const data=r?.data||{};modal(t.title,`<p class="meta">${e(areas[t.area])} · ${e(t.when)} · ${fmtDate(day)}</p>${t.note?`<div class="notice">${e(t.note)}</div>`:''}`+select('status','Como foi a execução?',[['done','Concluída'],['partial','Parcial'],['blocked','Bloqueada'],['pending','Pendente'],['na','Não se aplica']],data.status||'done')+field('responsible','Responsável pela execução',data.responsible||session.name)+textarea('note','Observação / motivo',data.note)+field('evidence','Evidência: link, referência ou quantidade',data.evidence)+`<p class="help">Execuções parciais, bloqueadas ou não aplicáveis exigem uma explicação. O histórico registra quem fez cada alteração.</p>`,'Salvar execução',async f=>saveRecord('run',{...data,...f,taskId:t.id,area:t.area,date:data.date||day,title:t.title},r,id))}
function entryModal(id){const r=record(id),d=r?.data||{};modal(r?'Acompanhar registro':'Novo registro',select('type','Tipo',[['occurrence','Ocorrência'],['unmet','Demanda não atendida'],['absence','Ausência'],['pending','Pendência']],d.type)+field('title','Título',d.title,'text',true)+field('client','Cliente / profissional relacionado',d.client)+`<div class="form-grid">${field('responsible','Responsável',d.responsible||session.name)}${field('due','Prazo de retorno',d.due,'date')}</div>`+select('status','Status',[['open','Aberta'],['progress','Em andamento'],['resolved','Resolvida']],d.status||'open')+textarea('note','Descrição e próximo passo',d.note),'Salvar registro',f=>saveRecord('entry',{...f,area:d.area||(area!=='all'?area:(roleArea(session.role)||'reception'))},r))}
function activationModal(id,kind){const r=record(id),d=r?.data||{};modal(r?'Acompanhar ativação':'Nova ativação',select('kind','Tipo de ativação',[...C.ATIVACOES.map(a=>[a.id,a.nome]),['conversion','Sequência de conversão'],['recovery','Recuperação de demanda'],...(retiredActivationLabels[d.kind]?[[d.kind,retiredActivationLabels[d.kind]]]:[])],d.kind||kind)+field('client','Cliente',d.client,'text',true)+`<div class="form-grid">${field('responsible','Responsável',d.responsible||session.name)}${field('due','Próxima ação em',d.due||businessDate(),'date',true)}</div>`+field('firstContact','Data do primeiro contato',d.firstContact||businessDate(),'date')+select('stage','Etapa da sequência',[['','Sem sequência'],...['D0','D1','D3','D5','D7'].map(x=>[x,x])],d.stage)+select('status','Resultado atual',[['pending','Pendente'],['contacted','Contato feito'],['scheduled','Agendada'],['completed','Concluída'],['dismissed','Encerrada sem conversão']],d.status||'pending')+textarea('note','Próxima ação e resultado',d.note)+`<p class="help">A sequência é acompanhada pela equipe. O sistema não envia mensagens automaticamente.</p>`,'Salvar acompanhamento',f=>saveRecord('activation',{...f,area:d.area||(area!=='all'?area:(roleArea(session.role)||'commercial'))},r))}
function routineModal(id){const r=record(id),d=r?.data||tasks().find(t=>t.id===id)||{area:view==='commercial'?'commercial':area};modal('Configurar rotina',field('title','Nome da rotina',d.title,'text',true)+select('area','Setor',Object.entries(areas),d.area)+select('schedule','Frequência',Object.entries(label).filter(([k])=>['daily','weekly','monthly','three','demand','review'].includes(k)),d.schedule)+field('when','Momento / condição',d.when||'Durante o dia')+`<label><span class="field-label">Dias da semana</span><div class="actions">${dayNames.map((n,i)=>`<label><input type="checkbox" name="day-${i}" ${d.days?.includes(i)?'checked':''}>${n}</label>`).join('')}</div></label>`+field('monthDay','Dia do mês (1–31; -1 para último dia)',d.monthDay||1,'number',false,'min="-1" max="31"')+textarea('note','Instruções e observações',d.note)+`<label><input type="checkbox" name="active" ${d.active!==false?'checked':''}> Rotina ativa</label>`,'Salvar configuração',(f,form)=>saveRecord('routine',{...d,...f,id:id||undefined,days:dayNames.map((_,i)=>i).filter(i=>form.elements['day-'+i].checked),monthDay:Number(f.monthDay),active:form.elements.active.checked},r,id))}
function clientModal(id){const r=record(id),d=r?.data||{};modal(r?'Perfil da cliente':'Conhecer uma cliente',`<p class="meta">Escolha, escreva ou pule. Compartilhe apenas o necessário para o cuidado.</p>`+C.questions.map(q=>q.type==='choices'?select(q.id,q.label,[['','Prefiro não informar'],...q.options.map(x=>[x,x])],d[q.id]):q.type==='textarea'?textarea(q.id,q.label,d[q.id]):field(q.id,q.label,d[q.id],q.type,q.id==='name')).join('')+`<label style="font-size:12px"><input type="checkbox" name="consent" ${d.consent?'checked':''}> Autorizo o E.Lab Boutique a enviar mensagens sobre agendamentos, novidades e cuidados no meu WhatsApp.</label><p class="help">A autorização é opcional e pode ser retirada editando este perfil. A equipe registra as informações com a cliente; este formulário permanece no espaço privado.</p>`,'Salvar perfil',(f,form)=>saveRecord('client',{...f,consent:form.elements.consent.checked},r))}
function inventoryModal(){modal('Cadastrar produto',field('name','Nome do produto','','text',true)+`<div class="form-grid">${field('quantity','Saldo conferido',0,'number',true,'min="0" step="0.01"')}${field('minimum','Estoque mínimo',0,'number',true,'min="0" step="0.01"')}</div>`+field('unit','Unidade','un')+field('supplier','Fornecedor')+field('expiry','Validade','', 'date'),'Cadastrar produto',f=>saveRecord('inventory',{...f,quantity:Number(f.quantity),minimum:Number(f.minimum)}))}
function stockModal(id){const r=record(id);modal('Movimentar · '+r.data.name,`<p class="notice">Saldo atual: ${r.data.quantity} ${e(r.data.unit)}</p>`+select('type','Movimento',[['in','Entrada'],['out','Saída'],['count','Contagem / ajuste de saldo']])+field('quantity','Quantidade','','number',true,'min="0" step="0.01"')+textarea('note','Motivo e documento de referência'),'Registrar movimento',f=>request('/api/stock',{...f,id,revision:r.revision,quantity:Number(f.quantity)}))}
function memberModal(email){const d=members.find(m=>m.email===email)||{};modal('Autorizar integrante',field('name','Nome',d.name,'text',true)+field('email','E-mail da conta ChatGPT',d.email,'email',true)+select('role','Função',Object.entries(roles).filter(([id])=>id!=='admin'),d.role||'reception')+`<label><input type="checkbox" name="active" ${d.active!==0?'checked':''}> Acesso ativo</label><p class="help">Compartilhe também este Site com a mesma pessoa nas opções de acesso da hospedagem.</p>`,'Salvar acesso',(f,form)=>request('/api/member',{...f,active:form.elements.active.checked}))}
function lessonModal(id){const lesson=C.TRILHA.flatMap(n=>n.missoes).find(m=>m.id===id),pop=C.POPS.find(p=>p.id===lesson.pop);modal(lesson.t,`<div class="reading"><p>${e(lesson.resumo)}</p><ol>${(pop?.steps||lesson.steps||[]).map(s=>`<li>${e(s)}</li>`).join('')}</ol>${pop?`<button type="button" class="btn small" data-action="open-linked-procedure" data-id="${e(pop.id)}">Consultar POP: ${e(pop.title)}</button>`:''}</div><div class="divider"></div><h3>Na prática</h3><p style="font-size:13px">${e(lesson.quiz.q)}</p>${lesson.quiz.opts.map((s,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" required>${e(s)}</label>`).join('')}`,'Verificar aprendizado',async f=>{const result=await request('/api/quiz',{lesson:id,answer:Number(f.answer)});if(!result.correct)throw Error(result.explanation);toast(result.explanation)})}
async function sendQueue(event){const r=record('queue/'+service);await request('/api/queue',{service,revision:r?.revision||0,operationId:crypto.randomUUID(),event});await refresh();toast('Lista atualizada.')}
function queueModal(type,name){
 const q=record('queue/'+service)?.data||{people:[]};
 if(type==='add'){
  const available=presenceState.staff.filter(p=>isOperationalStaff(p)&&!q.people.some(qp=>normalizedName(qp.name)===normalizedName(p.name)));
  if(!available.length)return toast('Nenhum profissional disponível para cadastro.');
  modal('Adicionar profissional',select('name','Profissional',available.map(p=>[p.name,p.name])),'Adicionar',f=>sendQueue({type:'add',name:f.name}));
 }
 if(type==='status'){const staff=presenceState.staff.find(p=>p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()===name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase());if(staff){const shift=presenceState.shifts.find(r=>r.data.staffId===staff.id);if(shift?.data.status!=='present'){navigate('presence');toast('Registre ou confira a presença de '+staff.name+' na equipe do dia.');return}modal('Disponibilidade · '+name,select('status','Disponibilidade na fila',[['present','Disponível'],['occupied','Em atendimento / ocupada']],q.people.find(p=>p.name===name)?.status),'Salvar disponibilidade',f=>sendQueue({type:'status',name,status:f.status}));}else modal('Presença · '+name,select('status','Status de hoje',[['present','Presente'],['occupied','Ocupada'],['absent','Ausente']],q.people.find(p=>p.name===name)?.status)+textarea('reason','Justificativa (obrigatória para ausência)'),'Confirmar status',f=>sendQueue({type:'status',name,status:f.status,reason:f.reason}));}
 if(type==='departure'){
  const person=q.people.find(p=>p.name===name);if(!person||!['present','occupied'].includes(effectiveStatus(person)))return toast('Só quem já estava presente pode ser marcado como tendo ido embora.',true);
  const staff=presenceState.staff.find(p=>normalizedName(p.name)===normalizedName(name));
  const shift=staff&&presenceState.shifts.find(r=>r.data.staffId===staff.id);
  if(staff&&shift?.data.status!=='present')return toast('Confira a chegada do profissional na página Presença.',true);
  modal('Confirmar saída · '+name,'<p>Marcar como ausente porque o profissional já foi embora. A chegada e o histórico de atendimentos serão preservados.</p>','Marcar ausente',()=>staff?presenceChange(shift.id,'departed','Profissional já foi embora.'):sendQueue({type:'status',name,status:'absent',reason:'Profissional já foi embora.'}));
 }
 if(type==='rename')modal('Renomear profissional',field('name','Nome atual',name,'text',true,'readonly')+field('newName','Nome corrigido',name,'text',true)+`<p class="help">O histórico anterior conserva o nome registrado na época.</p>`,'Salvar cadastro',f=>sendQueue({type:'rename',name,newName:f.newName}));
 if(type==='attendance')modal('Registrar atendimento · '+name,field('client','Cliente','','text',true)+field('service','Serviço realizado',SERVICES.find(([id])=>id===service)?.[1]||'','text',true)+`<p class="help">Este registro conta um atendimento e avança Agora uma única vez.</p>`,'Confirmar atendimento',f=>sendQueue({type:'attendance',name,client:f.client,service:f.service}));
 if(type==='schedule')modal('Agendamento futuro',field('client','Cliente','','text',true)+select('professional','Profissional da vez',agendaOrdered(q).slice(0,1).map(p=>[p.name,p.name]),name||agendaOrdered(q)[0]?.name)+field('service','Serviço',SERVICES.find(([id])=>id===service)?.[1]||'')+field('at','Data e hora (São Paulo)','','datetime-local',true),'Agendar',f=>sendQueue({type:'schedule',client:f.client,professional:f.professional,service:f.service,at:f.at+':00-03:00'}));
}
function attendanceModal(){modal('Registrar atendimento',field('client','Cliente','','text',true)+field('professional','Profissional','','text',true)+field('service','Serviço','','text',true)+field('date','Data',businessDate(),'date',true)+field('value','Valor realizado (R$)','','number',true,'min="0" step="0.01"'),'Salvar atendimento',f=>saveRecord('attendance',{...f,value:Number(f.value)}))}
function exportData(){const blob=new Blob([JSON.stringify({format:'elab-unificado-2',exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`elab-backup-${businessDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importModal(){modal('Importar backup',`<div class="notice">Aceita backups desta versão. Apenas registros novos serão adicionados. Dados existentes, acessos e auditoria não são sobrescritos.</div><label><span class="field-label">Arquivo JSON</span><input class="field" type="file" name="file" accept="application/json" required></label><p class="help">Treinamento é vinculado à identidade original e fica fora desta importação. Saldos existentes precisam de movimentação própria.</p>`,'Conferir e importar',async(f,form)=>{const file=form.elements.file.files[0];if(file.size>2000000)throw Error('Arquivo acima de 2 MB.');const data=JSON.parse(await file.text());if(data.format!=='elab-unificado-2'||!Array.isArray(data.records))throw Error('Formato de backup incompatível.');const list=data.records.filter(r=>!record(r.id)&&!['queue','training'].includes(r.kind));if(!confirm(`Importar ${list.length} registros novos? Os existentes serão preservados.`))throw Error('Importação cancelada.');let count=0;for(const r of list){await saveRecord(r.kind,r.data,undefined,r.id);count++}toast(`${count} registros importados.`)})}
app.addEventListener('input',ev=>{if(ev.target.id==='procedureQuestion')procedureDraft=ev.target.value;if(ev.target.id==='search'&&!ev.isComposing){search=ev.target.value;avecPage=stockPage=orderPage=0;const start=ev.target.selectionStart;render();const input=document.querySelector('#search');input?.focus({preventScroll:true});if(start!==null)input?.setSelectionRange(start,start)}});
app.addEventListener('submit',async ev=>{if(ev.target.id!=='profile-search-form')return;ev.preventDefault();profileSearch=new FormData(ev.target).get('profileName').trim();profilePage=0;await refreshSubmittedProfiles();render()});
app.addEventListener('change',ev=>{if(ev.target.id==='procedureSector'){procedureSector=ev.target.value;render()}if(ev.target.id==='dateFilter'){date=ev.target.value||businessDate();render()}if(ev.target.id==='areaFilter'){area=ev.target.value;render()}if(['historyType','historyFrom','historyTo'].includes(ev.target.id)){if(ev.target.id==='historyType')historyType=ev.target.value;if(ev.target.id==='historyFrom')historyFrom=ev.target.value;if(ev.target.id==='historyTo')historyTo=ev.target.value;render()}});
async function action(ev){const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{if(a==='toggle-menu')return setMenu(b.getAttribute('aria-expanded')!=='true');if(await featureAction(a,id))return;if(a==='close')return dialog.close();if(a==='integration-status')return loadIntegrationStatus();if(a==='panel-web')return sendPanelChat('web');if(a==='panel-monday-confirm')return sendPanelChat('monday',id);if(a==='panel-board-refresh')return refreshPanelBoard();if(a==='procedure-ask')return askProcedure();if(a==='procedure-favorite')return toggleProcedureFavorite(id);if(a==='open-linked-procedure'){const pop=C.POPS.find(p=>p.id===id);if(!pop)return;dialog.close();procedureSector='';navigate('procedures');search=pop.title;render();for(const item of app.querySelectorAll('details[data-procedure]'))if(item.dataset.procedure===id)item.open=true;return}if(a==='profile-copy-link'||a==='profile-copy-message'){const invite=profileInvitation();await navigator.clipboard.writeText(a==='profile-copy-link'?invite.url:invite.message);toast('Copiado.');return}if(a==='profiles-refresh'||a==='profiles-next'||a==='profiles-prev'){if(a==='profiles-next'&&profileHasNext)profilePage++;if(a==='profiles-prev'&&profilePage>0)profilePage--;await refreshSubmittedProfiles();render();return}if(a==='navigate')return navigate(id);if(a==='tab'){tab=id;return render()}if(a==='today'){date=businessDate();return render()}if(a==='open-day'){date=id;tab='today';return render()}if(a==='retry')return await refresh();if(a==='run')return runModal(id,b.dataset.date||record(id)?.data.date||date);if(a==='trigger'){const t=tasks().find(t=>t.id===id);const key=`run/${t.id}/${date}/${crypto.randomUUID()}`;return runModal(key,date,true)}if(a==='routine'){if(!management())throw Error('A configuração de rotinas é restrita à gestão.');return routineModal(id)}if(a==='entry')return entryModal(id);if(a==='activation')return activationModal(id);if(a==='new-activation-kind')return activationModal('',id);if(a==='go-entries'){view='relations';tab='entries';return render()}if(a==='go-catalog'){view='routines';tab='catalog';return render()}if(a==='client')return clientModal(id);if(a==='inventory'){if(!management())throw Error('O cadastro de produtos é restrito à gestão.');return inventoryModal()}if(a==='stock')return stockModal(id);if(a==='member')return memberModal(id);if(a==='lesson')return lessonModal(id);if(a==='service'){service=id;return render()}if(a==='queue-tab'){queueTab=id;return render()}if(a==='queue-add')return queueModal('add');if(a==='queue-status')return queueModal('status',id);if(a==='queue-depart')return queueModal('departure',id);if(a==='queue-schedule')return queueModal('schedule',id);if(a==='queue-rename')return queueModal('rename',id);if(a==='queue-attend')return queueModal('attendance',id);if(a==='queue-pass')return await sendQueue({type:'pass',name:id,mode:queueTab==='agenda'?'agenda':'now'});if(a==='appointment-confirm')return await sendQueue({type:'confirm-appointment',id});if(a==='appointment-no-show'&&confirm('Registrar que a cliente não compareceu?'))return await sendQueue({type:'no-show',id});if(a==='queue-remove'&&confirm('Retirar '+id+' desta fila?'))return await sendQueue({type:'remove',name:id});if(a==='queue-unschedule'&&confirm('Cancelar este agendamento e devolver a vez ao profissional na Agenda?'))return await sendQueue({type:'unschedule',id});if(a==='attendance')return attendanceModal();if(a==='export')return exportData();if(a==='import')return importModal();if(a==='history-export')return exportHistory(id);if(a==='audit')return await loadAudit();if(a==='detail')return detailsModal(id);if(a==='audit-detail')return detailsModal(id,true);if(a==='legacy-import')return legacyImportModal();if(a==='recovery')return await recoveryModal();if(a==='source-export')return exportSources();if(a==='local-recovery-help')return localRecoveryHelp();}catch(err){toast(err.message,true);if(/alter|atualiz/.test(err.message))await refresh(false)}}
