async function openTemporaryView(){
  const fragment = location.hash;
  if(!fragment.startsWith('#consulta='))return;
  const token = fragment.slice('#consulta='.length);
  window.history.replaceState(null,'',location.pathname+location.search);
  view='panel';
  await request('/api/temporary-view',{token});
}
